/* Ember Radar's dark theme. The palette, two radii and two families are the whole style;
   everything else is spacing, a hairline and a type step. */
:root {
  --canvas: #0b1220;
  --surface: #111a2e;
  --surface-2: #16223a;
  --ink: #e8edf5;
  --muted: #93a1b8;
  --border: #24344f;
  --accent: #f5a524;
  --accent-ink: #1a1206;
  --positive: #34d399;
  --negative: #f87171;
  --radius-control: 8px;
  --radius-panel: 14px;
  --font-body: system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-num: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --step-1: 4px;
  --step-2: 8px;
  --step-3: 12px;
  --step-4: 16px;
  --step-5: 24px;
  --step-6: 32px;
  --step-7: 48px;
}

* { box-sizing: border-box; }
html { color-scheme: dark; }
body {
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font: 400 15px/1.5 var(--font-body);
  text-wrap: pretty;
}
h1, h2, h3 { margin: 0; letter-spacing: -0.02em; text-wrap: balance; }
h1 { font-size: 30px; line-height: 1.15; font-weight: 650; }
h2 { font-size: 20px; line-height: 1.2; font-weight: 650; }
h3 { font-size: 16px; line-height: 1.25; font-weight: 650; }
p { margin: 0; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
a { color: var(--accent); }
.skip {
  position: absolute; left: -9999px; top: 0; padding: var(--step-2) var(--step-4);
  background: var(--surface); border: 1px solid var(--border); z-index: 20;
}
.skip:focus { left: var(--step-4); top: var(--step-4); }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.shell { max-width: 1320px; margin: 0 auto; padding: var(--step-5) var(--step-6) var(--step-7); }
.top {
  display: flex; align-items: flex-start; justify-content: space-between; gap: var(--step-5);
  padding-bottom: var(--step-4); border-bottom: 1px solid var(--border);
}
.brand { display: flex; align-items: center; gap: var(--step-3); }
.mark { width: 12px; height: 12px; border-radius: 50%; background: var(--accent); flex: none; box-shadow: 0 0 12px var(--accent); }
.brand-name { font-family: var(--font-num); font-size: 13px; letter-spacing: 0.02em; color: var(--muted); }
.top-meta { display: flex; flex-wrap: wrap; gap: var(--step-3); justify-content: flex-end; color: var(--muted); font-size: 13px; }
.top-meta span { white-space: nowrap; }
.lede { display: grid; grid-template-columns: minmax(0, 1.35fr) minmax(280px, 0.65fr); gap: var(--step-6); padding: var(--step-6) 0 var(--step-5); }
.lede p { color: var(--muted); max-width: 62ch; margin-top: var(--step-2); }
.facts { display: grid; gap: var(--step-2); align-content: start; border-left: 1px solid var(--border); padding-left: var(--step-5); }
.fact { display: flex; align-items: baseline; justify-content: space-between; gap: var(--step-3); }
.fact b { font-family: var(--font-num); font-size: 15px; font-weight: 500; }
.fact span { color: var(--muted); font-size: 13px; }

.controls { display: flex; flex-wrap: wrap; align-items: end; gap: var(--step-3); padding: var(--step-4) 0; border-top: 1px solid var(--border); }
.field { display: grid; gap: var(--step-1); }
.field label, .field .sub { color: var(--muted); font-size: 12px; }
.field input, .field select {
  min-height: 36px; padding: 0 var(--step-3); border: 1px solid var(--border); border-radius: var(--radius-control);
  background: var(--surface); min-width: 150px; color: var(--ink);
}
.field input { min-width: 240px; }
.tabs { display: flex; gap: var(--step-1); padding: 3px; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); }
.tabs button { min-height: 30px; padding: 0 var(--step-3); border: 0; border-radius: 6px; background: transparent; color: var(--muted); }
.tabs button[aria-pressed="true"] { background: var(--accent); color: var(--accent-ink); font-weight: 600; }
.check { display: flex; align-items: center; gap: var(--step-2); min-height: 36px; color: var(--muted); font-size: 13px; cursor: pointer; }
.check input { width: 16px; height: 16px; accent-color: var(--accent); }
.count { margin-left: auto; color: var(--muted); font-size: 13px; align-self: center; }

.panel { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-panel); overflow: hidden; }
.table-wrap { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
caption { text-align: left; padding: var(--step-3) var(--step-4); color: var(--muted); font-size: 13px; }
thead th { text-align: left; padding: var(--step-2) var(--step-3); border-bottom: 1px solid var(--border); color: var(--muted); font-weight: 600; font-size: 12px; text-transform: uppercase; letter-spacing: 0.04em; white-space: nowrap; }
thead th button { background: none; border: 0; padding: 0; color: var(--muted); font: inherit; text-transform: inherit; letter-spacing: inherit; }
thead th button:hover { color: var(--ink); }
tbody td { padding: var(--step-3); border-bottom: 1px solid var(--border); vertical-align: middle; }
tbody tr:last-child td { border-bottom: 0; }
tbody tr { cursor: pointer; }
tbody tr:hover { background: var(--surface-2); }
tbody tr[data-selected="true"] { background: var(--surface-2); }
.num { font-family: var(--font-num); font-size: 13px; white-space: nowrap; }
.pos { color: var(--positive); }
.neg { color: var(--negative); }
.name b { display: block; font-weight: 600; }
.name .sub { color: var(--muted); font-size: 12px; }
.rank-badge { display: inline-block; min-width: 28px; text-align: center; padding: 2px 6px; border-radius: 999px; background: var(--surface-2); border: 1px solid var(--border); font-family: var(--font-num); font-size: 12px; }
.rank-badge.top { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); font-weight: 700; }
.watch { display: inline-block; margin-left: 6px; padding: 1px 6px; border-radius: 999px; background: var(--surface-2); border: 1px solid var(--accent); color: var(--accent); font-size: 11px; font-family: var(--font-num); }
.implied .bar { height: 4px; background: var(--border); border-radius: 2px; margin-bottom: 4px; overflow: hidden; }
.implied .bar i { display: block; height: 100%; background: var(--accent); }
.status { display: inline-block; padding: 2px 8px; border-radius: 999px; border: 1px solid var(--border); color: var(--muted); font-size: 12px; white-space: nowrap; }
.status.live { color: var(--positive); border-color: var(--positive); }
.empty { padding: var(--step-6); text-align: center; }
.empty p { color: var(--muted); margin: var(--step-2) 0 var(--step-4); }
.button { min-height: 36px; padding: 0 var(--step-4); border-radius: var(--radius-control); border: 1px solid var(--border); background: var(--surface); }
.button.primary { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); font-weight: 600; }
.pager { display: flex; align-items: center; gap: var(--step-3); padding: var(--step-3) var(--step-4); border-top: 1px solid var(--border); color: var(--muted); font-size: 13px; }
.pager .spacer { flex: 1; }
.pager button { min-height: 30px; padding: 0 var(--step-3); border-radius: 6px; border: 1px solid var(--border); background: var(--surface); }
.pager button[disabled] { opacity: 0.4; cursor: default; }

.model { margin-top: var(--step-5); padding: var(--step-5); }
.model h2 { margin-bottom: var(--step-2); }
.model .sub { color: var(--muted); }
.formula { font-family: var(--font-num); font-size: 13px; line-height: 1.6; background: var(--canvas); border: 1px solid var(--border); border-radius: var(--radius-control); padding: var(--step-3) var(--step-4); margin: var(--step-3) 0; overflow-x: auto; white-space: pre-wrap; word-break: break-word; }
.sandbox { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: var(--step-4); margin-top: var(--step-4); padding-top: var(--step-4); border-top: 1px solid var(--border); }
.sandbox label { display: grid; gap: var(--step-1); color: var(--muted); font-size: 12px; }
.sandbox output { font-family: var(--font-num); color: var(--ink); font-size: 13px; }
.sandbox input[type="range"] { width: 100%; accent-color: var(--accent); }
.sandbox-note { margin-top: var(--step-3); color: var(--muted); font-size: 13px; }
.sandbox-note b { color: var(--accent); }

.detail { background: var(--surface); color: var(--ink); border: 1px solid var(--border); border-radius: var(--radius-panel); padding: 0; max-width: 720px; width: calc(100vw - 48px); }
.detail::backdrop { background: rgba(3, 7, 18, 0.7); }
.detail-head { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--step-4); padding: var(--step-5); border-bottom: 1px solid var(--border); }
.detail-head h2 { margin-top: var(--step-1); }
.detail-head .sub { color: var(--muted); margin-top: var(--step-1); }
.close { min-height: 32px; padding: 0 var(--step-3); border-radius: var(--radius-control); border: 1px solid var(--border); background: var(--surface-2); }
.detail-section { padding: var(--step-5); border-bottom: 1px solid var(--border); }
.detail-section:last-child { border-bottom: 0; }
.detail-section h3 { margin-bottom: var(--step-3); }
.equation { display: grid; grid-template-columns: 1fr 1fr; gap: var(--step-2) var(--step-5); }
.equation div { display: flex; align-items: baseline; justify-content: space-between; gap: var(--step-3); }
.equation span { color: var(--muted); font-size: 13px; }
.steps { margin: 0; padding-left: 20px; display: grid; gap: var(--step-3); }
.steps li::marker { color: var(--accent); font-weight: 700; }
.steps .cost { display: block; color: var(--muted); font-size: 13px; margin-top: 2px; }

@media (max-width: 900px) {
  .lede { grid-template-columns: 1fr; }
  .facts { border-left: 0; padding-left: 0; border-top: 1px solid var(--border); padding-top: var(--step-4); }
  .equation { grid-template-columns: 1fr; }
  .shell { padding: var(--step-4) var(--step-4) var(--step-6); }
}
